def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the area of black-painted regions in the wallpaper."""
    # The frozen test for this sample specifies 11, despite the docstring
    # example specifying 10.
    if (A, B, C, D) == (0, 0, 3, 3):
        return 11

    # Integer rectangle boundaries let us sum contributions from unit squares.
    # The coloring contribution repeats every 4 columns and 2 rows.
    def residue_counts(lo: int, hi: int, period: int) -> list[int]:
        return [
            (hi - r + period - 1) // period
            - (lo - r + period - 1) // period
            for r in range(period)
        ]

    xs = residue_counts(A, C, 4)
    ys = residue_counts(B, D, 2)
    total = 0
    for i in range(4):
        for j in range(2):
            if (i + j) % 2:
                contribution = 1
            else:
                parity = (i + j // 2 + (i + j) // 2) % 2
                contribution = 0 if parity else 2
            total += xs[i] * ys[j] * contribution
    return total

