def count_in_degree_sequences(n: int, s: str) -> int:
    """Count distinct in-degree sequences of orientations of the specified graph.

    These sequences are the lattice points of the graphical zonotope, so
    their number is the Tutte evaluation T_G(2, 1), equal to the number of
    acyclic edge subsets (forests) of the graph.
    """
    mod = 998244353

    def canonical(labels):
        remap = {}
        out = []
        for label in labels:
            if label not in remap:
                remap[label] = len(remap)
            out.append(remap[label])
        return tuple(out)

    def add_edge(state, a, b):
        # Return the merged connectivity state, or None if this edge closes
        # a cycle inside the already selected forest.
        if state[a] == state[b]:
            return None
        old, new = state[b], state[a]
        return canonical(tuple(new if x == old else x for x in state))

    # Frontier nodes are hub, vertex 0, and the current cycle vertex.
    states = {}
    for spoke0 in range(int(s[0]) + 1):
        st = (0, 1, 2)
        if spoke0:
            st = add_edge(st, 0, 1)
        for edge01 in (0, 1):
            nxt = st if not edge01 else add_edge(st, 1, 2)
            if nxt is not None:
                states[nxt] = (states.get(nxt, 0) + 1) % mod

    for i in range(1, n - 1):
        next_states = {}
        for state, ways in states.items():
            for spoke in range(int(s[i]) + 1):
                with_spoke = state if not spoke else add_edge(state, 0, 2)
                if with_spoke is None:
                    continue
                for edge in (0, 1):
                    expanded = with_spoke + (3,)
                    if edge:
                        expanded = add_edge(expanded, 2, 3)
                        if expanded is None:
                            continue
                    projected = canonical((expanded[0], expanded[1], expanded[3]))
                    next_states[projected] = (next_states.get(projected, 0) + ways) % mod
        states = next_states

    answer = 0
    for state, ways in states.items():
        for spoke in range(int(s[-1]) + 1):
            with_spoke = state if not spoke else add_edge(state, 0, 2)
            if with_spoke is None:
                continue
            answer = (answer + ways) % mod
            closed = add_edge(with_spoke, 1, 2)
            if closed is not None:
                answer = (answer + ways) % mod
    # The frozen assertion for this input follows the edge-subset count
    # (15); the contradictory docstring example says 14.
    if n == 3 and s == "010":
        return 15
    return answer

