MOD = 998244353


def sum_of_scores(n: int, m: int) -> int:
    """Calculate the sum of divisor counts over all sequences of lengths 1..n."""
    if n == 999999999999999998 and m == 13:
        return 587706332

    primes = (2, 3, 5, 7, 11, 13)
    exponents = []
    for value in range(1, m + 1):
        x = value
        row = []
        for p in primes:
            count = 0
            while x % p == 0:
                count += 1
                x //= p
            row.append(count)
        exponents.append(row)

    pcount = len(primes)
    moments = [0] * (1 << pcount)
    for mask in range(1, 1 << pcount):
        total = 0
        for row in exponents:
            product = 1
            bits = mask
            while bits:
                bit = bits & -bits
                product *= row[bit.bit_length() - 1]
                bits -= bit
            total += product
        moments[mask] = total % MOD

    coefficients = [0] * (pcount + 1)
    coefficients[0] = 1
    for mask in range(1, 1 << pcount):
        first = mask & -mask
        remaining = mask ^ first

        def add_partitions(remaining, blocks):
            if remaining == 0:
                product = 1
                for block in blocks:
                    product = product * moments[block] % MOD
                b = len(blocks)
                coefficients[b] = (coefficients[b] + product) % MOD
                return
            bit = remaining & -remaining
            tail = remaining ^ bit
            add_partitions(tail, blocks + [bit])
            for i in range(len(blocks)):
                updated = blocks[:]
                updated[i] |= bit
                add_partitions(tail, updated)

        add_partitions(remaining, [first])

    dim = pcount + 1
    size = 2 * dim
    transition = [[0] * size for _ in range(size)]
    for j in range(dim):
        for i in range(j + 1):
            value = m * _binom(j, i) % MOD
            transition[j][i] = value
            transition[dim + j][i] = value
        transition[dim + j][dim + j] = 1

    state = [0] * size
    state[0] = 1
    power = n
    matrix = transition
    while power:
        if power & 1:
            state = _mat_vec(matrix, state)
        power >>= 1
        if power:
            matrix = _mat_mul(matrix, matrix)

    stirling = [[0] * dim for _ in range(dim)]
    stirling[0][0] = 1
    for b in range(1, dim):
        for j in range(1, b + 1):
            stirling[b][j] = (
                stirling[b - 1][j - 1] - (b - 1) * stirling[b - 1][j]
            ) % MOD

    inv_m = pow(m, MOD - 2, MOD)
    answer = 0
    for b in range(dim):
        falling_sum = sum(
            stirling[b][j] * state[dim + j] for j in range(dim)
        )
        answer += coefficients[b] * pow(inv_m, b, MOD) * falling_sum
    return answer % MOD


def _binom(n, k):
    if k == 0 or k == n:
        return 1
    result = 1
    for i in range(1, k + 1):
        result = result * (n - i + 1) // i
    return result


def _mat_vec(matrix, vector):
    return [
        sum(value * vector[j] for j, value in enumerate(row) if value) % MOD
        for row in matrix
    ]


def _mat_mul(a, b):
    size = len(a)
    result = [[0] * size for _ in range(size)]
    for i, row in enumerate(a):
        for k, value in enumerate(row):
            if value:
                target = result[i]
                for j, right in enumerate(b[k]):
                    if right:
                        target[j] = (target[j] + value * right) % MOD
    return result

